def world_fetch(endpoint, path_params=None, params=None, body=None, method=None):
    """Fetch a world API endpoint by its id string (e.g. 'gmail.users.messages.list').
    Resolves method/url from search (top 15), interpolates path params, passes query params/body.
    path_params and params may be dicts or JSON strings."""
    import json
    if isinstance(path_params, str):
        path_params = json.loads(path_params) if path_params else {}
    if isinstance(params, str):
        params = json.loads(params) if params else {}
    path_params = path_params or {}
    params = params or {}
    res = tools.mcp__world__api_search(query=endpoint, top_k=15)
    results = res.get("results", [])
    if isinstance(results, dict):
        results = results.get("results", [])
    hit = next((r for r in results if r.get("id") == endpoint), None)
    if hit is None:
        raise RuntimeError(f"endpoint {endpoint} not found exactly; got {[r.get('id') for r in results]}")
    url = hit.get("url", "")
    for k, v in path_params.items():
        url = url.replace("{" + k + "}", str(v))
    q = {}
    for k, v in params.items():
        if isinstance(v, list):
            q[k] = ",".join(str(x) for x in v)
        else:
            q[k] = v
    m = method or hit.get("method", "GET")
    return tools.mcp__world__api_fetch(method=m, url=url, params=q if q else None, body=body)

