def check_availability(user_ids, day="2026-01-22"):
    """For each calendly-style user id, list scheduled events on `day` and return them
    plus a 'full day' flag (2+ events) / 'partial' (1 event)."""
    out = {}
    for uid in user_ids:
        r = tools.world_fetch(
            endpoint="calendly.scheduled_events.list",
            params={"user": uid, "min_start_time": day + "T00:00:00Z",
                    "max_start_time": day + "T23:59:59Z", "status": "active"},
        )
        events = (r or {}).get("collection") or []
        out[uid] = {
            "events": [(e.get("start_time"), e.get("end_time"), e.get("invitees")) for e in events],
            "event_count": len(events),
        }
    return out

